export type WaveShape = "sine" | "square" | "sawtooth" | "triangle";

export interface Oscillator {
  readonly frequency: number;    // Hz
  readonly shape:     WaveShape;
  readonly gain:      number;    // 0.0–1.0
  readonly detune:    number;    // cents — décalage fin en fréquence
}

// Spatial audio — encode la position orbitale en son
export interface SpatialAudio {
  readonly pan:      number;   // -1.0 (gauche) à +1.0 (droite)
  readonly distance: number;   // 0.0–1.0 → gain proportionnel
}

// Les 4 fréquences Solfège mappées aux états Crystal
export const STATE_FREQUENCIES = Object.freeze({
  Resonant:   639,   // connexion, cohérence — cœur
  Divergent:  741,   // expansion, éveil intuitif
  Convergent: 528,   // transformation, focalisation
  Instable:   417,   // changement, chaos créateur
} as const);

// angle orbital (0–360°) → pan stéréo (-1.0 à +1.0)
export function angleToPan(angleDeg: number): number {
  return Math.sin((angleDeg * Math.PI) / 180);
}

// CanSynthesize — Web Audio API disponible
export function canSynthesize(): boolean {
  return typeof AudioContext !== "undefined" ||
         typeof (window as any).webkitAudioContext !== "undefined";
}

