pub const FREQ_RESONANT:   f64 = 639.0;
pub const FREQ_DIVERGENT:  f64 = 741.0;
pub const FREQ_CONVERGENT: f64 = 528.0;
pub const FREQ_INSTABLE:   f64 = 417.0;

/// angle orbital (0–360°) → pan stéréo (-1.0 à +1.0)
/// Un sprite à 90° s'entend à droite. À 270° à gauche.
pub fn angle_to_pan(angle_deg: f64) -> f64 {
    (angle_deg.to_radians()).sin()
}

/// CanSynthesize — AudioContext disponible via web-sys
pub fn can_synthesize(ctx: &Option<web_sys::AudioContext>) -> bool {
    ctx.is_some()
}
